(()=>{'use strict';const $=s=>document.querySelector(s),bindings=new WeakMap();let current=null;
const elements=binding=>[...binding.doc.querySelectorAll('[data-site-style]')].filter(el=>el.dataset.siteStyle===binding.key);
const colorHex=value=>{const parts=value.match(/[\d.]+/g);return parts&&parts.length>=3?'#'+parts.slice(0,3).map(n=>Math.round(Number(n)).toString(16).padStart(2,'0')).join(''):'#192838';};
function sync(){const panel=$('#selectedTextLabel');if(!panel)return;const target=current&&elements(current)[0];for(const id of ['selectedFont','selectedFontSize','selectedTextColor','resetTextStyle'])$('#'+id).disabled=!target;if(!target){panel.textContent='برای انتخاب، روی متن پیش‌نمایش کلیک کنید.';return;}const style=current.config.textStyles?.[current.key]||{},computed=current.doc.defaultView.getComputedStyle(target);panel.textContent='متن انتخاب‌شده: '+target.textContent.trim().slice(0,65);$('#selectedFont').value=style.font||'';$('#selectedFontSize').value=style.size||Math.round(parseFloat(computed.fontSize));$('#selectedTextColor').value=style.color||colorHex(computed.color);}
function paint(binding){for(const el of binding.doc.querySelectorAll('[data-site-style]')){const style=binding.config.textStyles?.[el.dataset.siteStyle]||{};el.style.fontFamily=style.font||'';el.style.fontSize=style.size?style.size+'px':'';el.style.color=style.color||'';}}
function change(prop,value){if(!current?.key)return;const config=current.config;config.textStyles ||= {};const style={...(config.textStyles[current.key]||{})};if(value==='')delete style[prop];else style[prop]=value;config.textStyles[current.key]=style;paint(current);current.mark();}
$('#selectedFont')?.addEventListener('change',event=>change('font',event.target.value));$('#selectedFontSize')?.addEventListener('input',event=>{const n=Number(event.target.value);if(event.target.value&&Number.isFinite(n)&&n>=8&&n<=96)change('size',n);});$('#selectedTextColor')?.addEventListener('input',event=>change('color',event.target.value));$('#resetTextStyle')?.addEventListener('click',()=>{if(!current)return;delete current.config.textStyles[current.key];paint(current);current.mark();sync();});
window.PBSiteTextEditor={install(doc,config,mark){let binding=bindings.get(doc);if(!binding){binding={doc,config,mark,key:''};bindings.set(doc,binding);const select=target=>{const el=target?.nodeType===1?target:target?.parentElement,key=el?.closest('[data-site-style]')?.dataset.siteStyle;if(!key)return;binding.key=key;current=binding;$('#textStylePanel').open=true;doc.querySelectorAll('.site-selected-text').forEach(node=>node.classList.remove('site-selected-text'));elements(binding).forEach(node=>node.classList.add('site-selected-text'));sync();};doc.addEventListener('click',event=>select(event.target));doc.addEventListener('focusin',event=>select(event.target));doc.addEventListener('selectionchange',()=>{const selection=doc.getSelection();if(selection&&!selection.isCollapsed)select(selection.anchorNode);});const style=doc.createElement('style');style.textContent='.site-selected-text{outline:2px solid #315efb!important;outline-offset:3px;border-radius:3px}';doc.head.append(style);}binding.config=config;binding.mark=mark;paint(binding);if(current?.doc===doc){current=binding;sync();}}};sync();})();
